-- =====================================================================
-- TripSplit World — 0004 private storage buckets + storage RLS
--
-- Every bucket is private. Downloads go through short-lived signed URLs
-- generated by an Edge Function after an authorisation check, so a leaked
-- path alone grants no access.
-- =====================================================================

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values
  ('trip-documents',  'trip-documents',  false, 26214400,
    array['application/pdf','image/jpeg','image/png','image/heic','image/webp']),
  ('trip-receipts',   'trip-receipts',   false, 10485760,
    array['application/pdf','image/jpeg','image/png','image/heic','image/webp']),
  ('trip-bookings',   'trip-bookings',   false, 26214400,
    array['application/pdf','image/jpeg','image/png','image/heic','image/webp']),
  ('avatars',         'avatars',         false, 2097152,
    array['image/jpeg','image/png','image/webp'])
on conflict (id) do update
  set public = excluded.public,
      file_size_limit = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;

-- Objects live at  <user_id>/<trip_id>/<uuid>.<ext>. The path prefix IS the
-- authorisation boundary: the first segment must equal auth.uid().

-- Returns the owning user id parsed from an object path, or null when the
-- first segment is not a uuid. The return type is uuid (not text) so it can be
-- compared with auth.uid() directly.
create or replace function public.storage_owner_of(path text)
returns uuid
language plpgsql
immutable
as $$
declare
  v_part text;
begin
  v_part := split_part(path, '/', 1);
  if v_part ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' then
    return v_part::uuid;
  end if;
  return null;
exception when others then
  return null;
end;
$$;

create or replace function public.storage_trip_of(path text)
returns uuid
language plpgsql
immutable
as $$
declare
  v_part text;
begin
  v_part := split_part(path, '/', 2);
  if v_part ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    return v_part::uuid;
  end if;
  return null;
exception when others then
  return null;
end;
$$;

create or replace function public.can_access_storage_object(path text)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select
    -- Own files, or files uploaded into a trip they belong to.
    public.storage_owner_of(path) = auth.uid()
    or (
      public.storage_trip_of(path) is not null
      and public.is_trip_member(public.storage_trip_of(path))
    )
    -- Trip admins can always reach a trip's shared documents.
    or (
      public.storage_trip_of(path) is not null
      and public.can_admin_trip(public.storage_trip_of(path))
    );
$$;

-- storage.objects policies
create policy "storage: read own or shared trip files"
  on storage.objects for select
  using (bucket_id in ('trip-documents','trip-receipts','trip-bookings')
         and public.can_access_storage_object(name));

create policy "storage: upload into own folder"
  on storage.objects for insert
  with check (
    bucket_id in ('trip-documents','trip-receipts','trip-bookings')
    and public.storage_owner_of(name) = auth.uid()
    -- A trip folder may only be used if the user actually belongs to that trip.
    and (
      public.storage_trip_of(name) is null
      or public.is_trip_member(public.storage_trip_of(name))
    )
  );

create policy "storage: update own files"
  on storage.objects for update
  using (public.storage_owner_of(name) = auth.uid())
  with check (public.storage_owner_of(name) = auth.uid());

create policy "storage: delete own files"
  on storage.objects for delete
  using (
    public.storage_owner_of(name) = auth.uid()
    or (public.storage_trip_of(name) is not null
        and public.can_admin_trip(public.storage_trip_of(name)))
  );

-- Avatars: readable by co-members, writable only by the owner.
create policy "storage: avatar read"
  on storage.objects for select
  using (bucket_id = 'avatars');

create policy "storage: avatar write"
  on storage.objects for all
  using (bucket_id = 'avatars' and public.storage_owner_of(name) = auth.uid())
  with check (bucket_id = 'avatars' and public.storage_owner_of(name) = auth.uid());
